(function(){"use strict";const examMode=!!window.__mkExamMode;const pages=[{id:"home",title:"Find your route",kind:"page",priority:10,surface:"[data-wiki-home]",path:"(?:^|/)(?:index\\.html)?$",steps:[{title:"Begin with a task",text:"Choose Explore Year 1 for course notes or Find a concept for a named idea. The cards also offer revision and teaching routes.",target:".wh-actions",visual:"list",action:"Choose the route that fits today's question."},{title:"Check coverage",text:"Check each year's coverage before choosing a course. Year 1 has the fullest notes; Year 2 has hubs, and Year 3 has no course material yet.",target:".wh-coverage",visual:"progress"},{title:"Use the shorter routes",text:"Open the site guide, rankings or contributors from the footer. Personal activities are optional and separate from course grades.",target:".wh-footer-links",visual:"list"}]},{id:"exam-home",title:"Navigate Exam Mode",kind:"page",priority:10,surface:".hero",path:"(?:^|/)(?:index\\.html)?$",when:()=>examMode,steps:[{title:"Open a course or Finder",text:"Choose Year 1 for course notes, or Concept Finder to search published concepts. The header search also accepts titles, aliases, course codes and lecture tags.",target:".hero-actions",visual:"search"},{title:"Use local study tools",text:"Open Course diagnostics, mastery or maps for browser-local study records. Use Self-test only where its control appears; the Exam guide explains availability.",target:"article.md-content__inner",visual:"progress"},{title:"Know what is unavailable",text:"Open About Exam Mode before planning a workflow. Accounts, cloud sync, comments, rankings, Store and AI checks are unavailable in this mirror.",target:".hero-actions a[href*='about']",visual:"privacy"}]},{id:"header-search",title:"Search from any page",kind:"panel",priority:84,surface:".md-search",when:root=>root.matches(":focus-within")&&(!!root.querySelector(".md-search__input:focus")||!!root.querySelector("[data-wiki-guide-ui]")),steps:[{title:"Search a title or code",text:"Enter a concept name, alias, course code or lecture tag. Suggestions can open a concept directly; the full results page offers a wider list.",target:".md-search__input",visual:"search",example:"m1c-lecture02"},{title:"Open the right result",text:"Check the course and title before opening a suggestion. If the list is broad, move to Concept Finder to combine tokens and select a revision pool.",target:".md-search__output",visual:"list",action:"Choose a matching result or open Finder."}]},{id:"explore-menu",title:"Use the Explore menu",kind:"panel",priority:86,surface:"#mk-random-tabs-random-panel",when:root=>root.style.visibility==="visible",steps:[{title:"Choose a discovery route",text:examMode?"Open Concept Finder for a focused pool, Random Concept for an unvisited idea, or Random Route for a guided connection through published notes.":"Open Finder for a focused pool, Random Concept for an unvisited idea, Random Route for a guided connection, or Random AI Quiz for an available check.",target:".mk-rt-panel-item, a",visual:"search"},{title:"Keep the scope in view",text:"Use your course hub or Finder for a particular lecture or prerequisite. Random routes explore available notes without prescribing a study order.",target:"#mk-random-tabs-random-panel",visual:"list"}]},{id:"year-menu",title:"Choose a study year",kind:"panel",priority:85,surface:"#mk-random-tabs-year-panel",when:root=>root.style.visibility==="visible",yieldTo:"#rf-year-course-popover-v4.rf-year-course-popover-open-v4, #mk-random-tabs-year-panel.mk-rt-mobile-year-course-panel",steps:[{title:"Open the year directory",text:"Select a year name to open its directory; on narrow screens, use the adjacent arrow to browse its courses. Year 1 has the fullest notes; later years have varying coverage.",target:"#mk-random-tabs-year-panel .mk-rt-year-text-btn, #mk-random-tabs-year-panel a.mk-rt-panel-item",visual:"list"}]},{id:"rankings-menu",title:"Choose a rankings board",kind:"panel",priority:87,surface:"#mk-random-tabs-trending-panel",when:root=>!examMode&&root.style.visibility==="visible",steps:[{title:"Choose a metric first",text:"Choose Most Viewed, Most Popular or Most Tested concepts, or open the available user, EOR Rating and Collection Value boards. Each page explains its period and eligibility.",target:".mk-rt-panel-item, a",visual:"progress"},{title:"Respect visibility choices",text:"Read rankings as selected activity, not grades or a full learning record. Someone may be absent because they opted out.",target:"#mk-random-tabs-trending-panel",visual:"privacy"}]},{id:"my-menu",title:"Find your personal tools",kind:"panel",priority:88,surface:"#mk-random-tabs-activity-panel",when:root=>!examMode&&root.style.visibility==="visible",steps:[{title:"Open account and messages",text:"Open Account for profile, privacy, connections and sync; use the direct menu shortcuts for notifications and your public profile.",target:".mk-rt-panel-item",visual:"profile"},{title:"Resume learning work",text:"Choose Resume review for an unfinished session, Study sets for saved queues, or Saved pages for bookmarks. These records have different storage boundaries.",target:"#mk-random-tabs-activity-panel",visual:"list"},{title:"Explore optional activities",text:"Open My collection, Arena or Store for their rules before spending or entering an event. These activities are separate from course grades.",target:"#mk-random-tabs-activity-panel",visual:"shop"}]},{id:"sidebar-course-picker",title:"Switch courses in the sidebar",kind:"panel",priority:89,surface:"#current-course-bar[data-course-menu-open='1'] .ccb-menu:not([hidden])",steps:[{title:"Choose a course",text:"Choose another course to open its hub, then use sidebar links for lectures and concepts. The current course is marked in this menu.",target:".ccb-menu-item",visual:"list"},{title:"Return without switching",text:"Press Escape or click outside to close the picker. The Course control shows your current scope and does not change the concept page by itself.",target:"#current-course-bar .ccb-course-trigger",visual:"search"}]},{id:"sidebar-sort",title:"Order sidebar topics",kind:"panel",priority:78,surface:"#mk-sidebar-sortdock",when:root=>root.matches(":focus-within"),steps:[{title:"Choose an ordering",text:"Click Sort by to cycle the sidebar order for this year or course. Sorting changes presentation without altering concepts or your learning record.",target:".msb-sortdock__btn",visual:"list"},{title:"Open a topic",text:"After sorting, use a course or lecture group to expand its concept links. The course picker above the sort control changes which course index is open.",target:".md-nav__list, #current-course-bar .ccb-course-trigger",visual:"search"}]},{id:"concept-sidebar",title:"Use the course directory",kind:"page",priority:77,manualOnly:true,surface:"#mk-mobile-unified-sidebar-surface, .md-sidebar--primary",path:"(?:^|/)Year-[123]/[^/]+/(?!index\\.html)[^/]+\\.html$",when:root=>{const box=root.getBoundingClientRect();return box.right>0&&box.bottom>0&&box.left<innerWidth&&box.top<innerHeight;},steps:[{title:"Stay in the right course",text:"The Course control shows the current course. Open it to choose another course hub; choosing a course does not change this concept until you follow a link.",target:"#current-course-bar .ccb-course-trigger",visual:"list",optional:true},{title:"Expand a group",text:"Open or close a lecture or topic group to find its concept links. Follow a title to read that page; the group heading only changes this directory.",target:".msb-group-head__btn, .md-nav__item .md-nav__toggle, .md-nav__list",visual:"list"},{title:"Change the order",text:"Use Sort by when shown to reorder this directory. Sorting does not change notes or your learning record.",target:"#mk-sidebar-sortdock .msb-sortdock__btn",visual:"settings",optional:true}]},{id:"year-overview",title:"Browse a study year",kind:"page",priority:12,surface:".year-hero",path:"(?:^|/)Year-[123]/(?:index\\.html)?$",steps:[{title:"Choose the block",text:"Open a course title within its block to reach the hub, where published concepts and lecture or week links are organised.",target:".year-block",visual:"list",action:"Pick the course you are studying."},{title:"Use topic shortcuts",text:"Open a linked topic chip for a concept page when one is available. Check each year's availability notice before planning a full revision route.",target:".course-card--topics a.topic-pill[href]",visual:"search",optional:true}]},{id:"course-hub",title:"Work through a course",kind:"page",priority:20,surface:".course-home",path:"(?:^|/)Year-[123]/[^/]+/(?:index\\.html)?$",steps:[{title:"Pick the way in",text:"Choose a task card for course search, a lecture or week, a topic group, or teaching preparation where available.",target:".ch-task-grid",visual:"list"},{title:"Search inside this course",text:"Enter a title or term and submit Search in course. Use the Finder link below when you want filters, multiple concepts or a saved set.",target:".course-search",visual:"search",example:"limit"},{title:"Return to your unit",text:"Choose a lecture or week tile to open its tagged concepts in Finder. These tags organise published pages; confirm the teaching schedule in your course materials.",target:".ch-unit-grid",visual:"list"},{title:"Open one concept",text:"Expand a topic group and follow a concept link. Course diagnostics, if shown beside the title, summarises your personal records rather than course grades.",target:".ch-concept-grid",visual:"progress"}]},{id:"course-library",title:"Browse this course library",kind:"page",priority:20,surface:".course-search[data-course-token]",path:"(?:^|/)Year-[123]/[^/]+/(?:index\\.html)?$",when:()=>!document.querySelector(".course-home"),steps:[{title:"Search within this course",text:"Enter a topic and press Search in course. The results below the box are limited to this course; Finder can combine its code with other terms.",target:"#course-search-form",visual:"search",example:"simplex"},{title:"Browse a block or week",text:"Open a concept from the grouped headings, or use an available All Week link to see the full tagged pool in Finder.",target:"article.md-content__inner h2, .course-block",visual:"list"},{title:"Check your own progress",text:"Open Course diagnostics beside the title for visits, ratings and readiness. Unrated concepts are unassessed, not failed; these are study records, not grades.",target:"[data-course-mastery-map], .cmm-h1-entry",visual:"progress"}]},{id:"course-placeholder",title:"Read an unwritten course notice",kind:"page",priority:19,surface:"article.md-content__inner .admonition.info",path:"(?:^|/)Year-[123]/[^/]+/(?:index\\.html)?$",steps:[{title:"Check availability",text:"Read this course's availability notice, then use your course learning environment for current materials. The hub has no concept notes here yet and promises no date.",target:".admonition.info",visual:"list"},{title:"Continue with available material",text:"Search Concept Finder for published notes, or open Year 1 to find courses with concept coverage and related foundations.",target:".admonition.info a",visual:"search"}]},{id:"year-three",title:"Year 3 availability",kind:"page",priority:12,surface:"article.md-content__inner",path:"(?:^|/)Year-3/(?:index\\.html)?$",steps:[{title:"Use the current course materials",text:"Use your course learning environment for Year 3 teaching; this Wiki has no Year 3 course pages yet. Finder and other years contain published concepts.",target:"article.md-content__inner",visual:"search"}]},{id:"concept-page",title:"Read and practise a concept",kind:"page",priority:18,surface:"article.md-content__inner",path:"(?:^|/)Year-[123]/[^/]+/(?!index\\.html)[^/]+\\.html$",steps:[{title:"Read and try the idea",text:"Read the definition, interpretation and example, then explain the idea in your own words. Follow a linked term when an assumption is unfamiliar.",target:"h2.rf-h2, h2",visual:"practice",action:"Try explaining the concept in your own words."},{title:"Explore a connected idea",text:"Follow a linked concept to unpack an unfamiliar term. Use Concept connections for recorded prerequisites and later uses; some concepts have no suggested connections.",target:"article.md-content__inner p a[href*='.html'], article.md-content__inner li a[href*='.html'], .lp-head",visual:"map"},{title:"Record your understanding",text:examMode?"Choose Unknown, Partial, Clear or Mastered in the understanding bar when it appears. Reading alone does not rate you; Exam Mode stores ratings here.":"Choose Unknown, Partial, Clear or Mastered in the understanding bar when it appears. Reading alone does not rate you; your choice is personal.",target:"#mw-mastery .mw-row [data-m], .mw-title-badge",visual:"progress",optional:true},{title:"Browse the course directory",text:"The left directory groups notes by lecture or topic. On a small screen, the menu button opens it; sorting changes only its order.",target:"#current-course-bar .ccb-course-trigger, .md-header [for='__drawer']",visual:"list",optional:true},{title:"Explore Concept connections",text:"This area collects recorded foundations, later uses and related ideas. On a small screen, open its sheet to reach the lists and maps.",target:"#lp-side-panel .lp-head, #lp-mobile-sheet .lp-msheet-head",visual:"map",optional:true},{title:"Check sources and discuss",text:examMode?"Read Sources at the end of the note for its course or lecture attribution. Check current teaching and assessment rules in your course materials; comments are unavailable in Exam Mode.":"Read Sources for the note's course or lecture attribution. Check current teaching and assessment rules in your course materials; Comments below lets you ask a focused question when available.",target:"#sources",visual:"list",optional:true}]},{id:"concept-sources",title:"Check a concept's sources",kind:"page",priority:76,manualOnly:true,surface:"article.md-content__inner #sources",path:"(?:^|/)Year-[123]/[^/]+/(?!index\\.html)[^/]+\\.html$",steps:[{title:"Read the page attribution",text:"The Sources section identifies the course, lecture or other source recorded for this Wiki note. It does not certify that the page covers the whole unit.",target:"#sources",visual:"list"},{title:"Check the current course",text:"Follow a linked course or lecture when one is shown, and compare the note with your lecturer's current syllabus and assessment guidance.",target:"#sources + ul a[href], #sources + p a[href], #sources + ul, #sources + p",visual:"search",optional:true}]},{id:"page-actions",title:"Save or share this concept",kind:"panel",priority:91,surface:".mk-page-action-menu:not([hidden])",steps:[{title:"Choose a saved-page purpose",text:"Save this page as Favourite, Study later or Review later. Review later is a bookmark, not a study-set session; select an active item again to remove it.",target:".mk-page-action-item[data-action]",visual:"list"},{title:"Use the other actions",text:examMode?"Use the local page actions shown here. Account recommendations and edit requests are unavailable in Exam Mode.":"Recommend this page to a study connection if connected, or open Edit page to suggest a correction. Suggestions do not change the published note directly.",target:".mk-page-action-item",visual:"share"}]},{id:"mastery-title-menu",title:"Choose an understanding level",kind:"panel",priority:92,surface:".mw-title-menu",steps:[{title:"Rate current understanding",text:"Choose Mastered, Clear, Partial or Unknown after trying the concept. An unrated page is distinct from Unknown; your selection records a personal judgement, not a course mark.",target:".mw-title-menu-levels [data-m]",visual:"progress"},{title:"Inspect the evidence",text:examMode?"Open Prereq for foundation readiness, Recap for local activity, or Manage mastery for browser records. AI checks are unavailable in Exam Mode.":"Open Prereq for foundation readiness, Recap for recent activity, or Manage mastery for your record; use an available AI check for practice.",target:".mw-title-menu-btn--ready, .mw-title-menu-btn--recap, .mw-title-menu-btn--manage",visual:"practice"},{title:"Control the bar",text:"Use the eye control to hide or show the bar before rating. After a rating, use the title badge to reopen its controls.",target:".mw-title-menu-btn--toggle, .mw-title-badge",visual:"settings",optional:true}]},{id:"mastery-bar",title:"Use the understanding bar",kind:"panel",priority:79,surface:"#mw-mastery",when:root=>root.matches(":focus-within"),steps:[{title:"Understand the levels",text:"Open the information button for the four level meanings. Pick the level that matches what you can explain now; no rating and Unknown are different states.",target:".mw-level-info, .mw-row [data-m]",visual:"progress"},{title:"Check foundations and history",text:"Open Prereq for linked foundation ratings, Recap for visits and reviews, or Manage mastery for the wider record.",target:"[data-mw-ready-trigger], [data-mw-recap-trigger], [data-mw-manage]",visual:"progress"},{title:"Keep the page readable",text:"Choose Hide to collapse the bar before rating; reopen it from the title control. Hiding does not erase ratings or visits.",target:"[data-mw-hide]",visual:"settings"}]},{id:"mastery-level-info",title:"Interpret understanding levels",kind:"panel",priority:96,surface:"#mw-level-info-dialog[open]",steps:[{title:"Choose honestly",text:"Read the examples for Mastered, Clear, Partial and Unknown, then close this explanation to rate the concept. These labels are private learning notes, not course grades.",target:".mw-level-info-list, .mw-level-info-close",visual:"progress"}]},{id:"mastery-prerequisites",title:"Read prerequisite readiness",kind:"panel",priority:95,surface:"#mw-ready-popover:not([hidden])",steps:[{title:"Read the score as a signal",text:"Read prerequisite readiness as a weighted signal from linked foundations. Direct links count more; Not assessed means no explicit rating, not zero understanding.",target:".mw-ready-score-card, .mw-ready-formula",visual:"progress"},{title:"Open a weak foundation",text:"Follow a direct or indirect prerequisite link to test a missing step. Inspecting its score does not change your rating here.",target:".mw-ready-list, .mw-ready-link",visual:"map"}]},{id:"mastery-recap",title:"Read your concept recap",kind:"panel",priority:95,surface:"#mw-recap-popover:not([hidden])",steps:[{title:"Review your own timeline",text:"Read Recap for your rating and recorded visits, reviews and rating changes. An empty history says nothing about your understanding.",target:".mw-recap-rating, .mw-recap-list",visual:"progress"},{title:"Choose the next action",text:"Return to the note to test yourself, or open Manage mastery to filter the wider record. The recap reports activity; it does not award a grade.",target:"#mw-recap-popover",visual:"practice"}]},{id:"concept-comments",title:"Discuss a concept",kind:"panel",priority:77,manualOnly:true,surface:".mk-page-comments",steps:[{title:"Read this page's discussion",text:"Comments belong to this concept page. If the list is empty or cloud loading fails, the note above remains available for study.",target:".mk-comments-head",visual:"list"},{title:"Write a focused question",text:"Use the composer to ask about this concept or suggest a correction. A name is optional for guests; a connected learner may choose anonymous posting before sending.",target:".mk-comment-composer textarea, .mk-comment-anon-row, .mk-comment-name-input",visual:"share",optional:true},{title:"Read and organise replies",text:"Sort comments by newest, oldest or most popular. Open replies beneath a comment; use Reply to continue that thread rather than starting an unrelated one.",target:".mk-comments-sort-trigger, .mk-comment-list, .mk-comment-replies-toggle",visual:"list",optional:true},{title:"Correct or flag a comment",text:"Edit or delete your own comment, or use Report on another comment. Check the visible status to confirm the action was accepted.",target:".mk-comment-actions, .mk-comment-report-btn",visual:"privacy",optional:true}]},{id:"self-test",title:"Try the concept before revealing it",kind:"page",priority:80,surface:"article.md-content__inner",path:"(?:^|/)Year-[123]/[^/]+/(?!index\\.html)[^/]+\\.html$",when:root=>{if(!root.querySelector(".rf-body[hidden]"))return false;if(window.MkConceptFold?.isSelfTestEnabled?.())return true;try{return window.sessionStorage.getItem("random_review_mode_v1")==="1";}catch(_){return false;}},steps:[{title:"Try recall first",text:"State the definition or work an example before opening a folded section. This Self-test reading mode records neither a score nor a mastery rating.",target:"h2.rf-h2 .rf-toggle",visual:"practice",action:"Answer in your own words before revealing."},{title:"Reveal and compare",text:"Open a heading to check the definition, intuition or example. If you missed a step, follow its prerequisite link and return to the same question.",target:"h2.rf-h2 .rf-toggle, .rf-body:not([hidden])",visual:"practice"},{title:"Record a separate judgement",text:examMode?"Choose a mastery level only after checking your understanding. This local rating stays in the current browser and does not change merely because you revealed the page.":"Choose a mastery level only after checking your understanding. A review session's Done & next records the session step separately.",target:".mw-title-badge, h1",visual:"progress"}]},{id:"finder",title:"Find and select concepts",kind:"page",priority:22,surface:".wiki-finder",path:"(?:^|/)find\\.html$",steps:[{title:"Start with a simple search",text:"Search a concept, course code or lecture tag, then press Search.",target:"#fb-simple-search, #search-form",visual:"search",example:"m1c-lecture02"},{title:"Build a precise query",text:examMode?"Open Advanced query to combine terms with AND, OR and parentheses. Its example shows the board layout; saved sets and AI-test are unavailable in Exam Mode.":"Open Advanced query to combine reusable terms with AND, OR and parentheses. Its example button shows the board layout before you write an expression.",target:"#fb-search-mode",visual:"search",example:"m1c AND (derivative OR integral)"}]},{id:"finder-query",title:"Build an advanced query",kind:"panel",priority:70,surface:"#wf-query-editor",when:()=>!!document.querySelector("#fb-search-mode[aria-expanded='true']"),steps:[{title:"Add a searchable term",text:"Type a title, alias, course code or lecture tag and press Enter. The token pool keeps terms for reuse without running a search.",target:"#search-input, .fb-tokensearch-dropdown",visual:"search",example:"m1c-lecture02"},{title:"Place terms on the board",text:"Choose a token in the pool to insert it at the highlighted slot. Select another insertion slot before adding the next term; the example button loads a working expression.",target:".fb-tokenbtn, .fb-slot, [data-fb-example]",visual:"list",example:"m1c AND limit"},{title:"Choose the logic",text:"Use AND for both terms, OR for either, and parentheses to group alternatives. Check the board before running your expression.",target:"#fb-and, #fb-or, #fb-lp, #fb-rp",visual:"search",example:"m1c AND (limit OR derivative)"},{title:"Edit without retyping",text:"Move or remove a chip, then use Undo or Redo if needed. Clear resets the board; Clear tokens also removes pool terms.",target:".fb-chip__move, #fb-undo, #fb-redo, #fb-clear, #fb-clear-tokens",visual:"list"},{title:"Run and check the result",text:"Choose Run search, then check Current search above the results. Draft edits do not apply until run; Edit as typed restores an unwanted correction.",target:"#fb-run",visual:"search"}]},{id:"finder-results",title:"Use search results",kind:"panel",priority:72,surface:"#search-results",when:root=>!!root.querySelector(".csr-wrap.is-visible .csr-result-summary"),steps:[{title:"Confirm the applied query",text:"Check Current search and the match count before using results. If the editor says Draft changed, run the new query first.",target:".wf-query-summary",visual:"search"},{title:"Narrow and order the list",text:"Use Filters for states such as Unvisited or Unrated, and Sort for relevance or course order. These controls do not change the search expression.",target:"[data-sr-toggle='filters'], #csr-filter-panel, .mk-sortbtn",visual:"search"},{title:"Select a revision pool",text:"Use None to clear the initially selected results, then tick a few rows. All and None affect filtered results across pages; pagination changes only visibility.",target:"#cr-none",visual:"list"},{title:"Choose the reading mode",text:examMode?"Open Revision for ordinary reading or folded Self-test. AI-test and Store unlocks are unavailable in Exam Mode.":"Open Revision for ordinary reading, folded Self-test or an AI-test question. Some modes require a Store unlock; AI checking also needs internet access.",target:"[data-sr-toggle='revision'], #csr-revision-panel",visual:"practice"},{title:"Use the selection",text:examMode?"Start random from eligible selected concepts. Enrichment and retired pages remain searchable but cannot enter random revision; open the selection explanation for exclusions.":"Start random from eligible selected concepts or Save as set for an ordered local list. Open the selection explanation for excluded enrichment or retired pages.",target:examMode?"#cr-random, [data-sr-selection-explanation]":"#cr-random, [data-study-set-create], [data-sr-selection-explanation]",visual:"list"}]},{id:"finder-empty-results",title:"Recover from an empty search",kind:"panel",priority:72,surface:"#search-results",when:root=>!!root.querySelector(".csr-result-summary + .sr-empty"),steps:[{title:"Check what was searched",text:"Read Current search to confirm the applied query. Advanced drafts need Run search; a narrow course or lecture tag may also explain zero matches.",target:".wf-query-summary",visual:"search"},{title:"Broaden one condition",text:"Remove one AND condition or try a broader word, then run again. Use Edit as typed if a suggested correction changed your intent.",target:"[data-wf-edit], #fb-search-mode, [data-fb-fuzzy-act='edit']",visual:"search"}]},{id:"study-sets-empty",title:"Build your first study set",kind:"panel",priority:91,surface:"#study-sets-workspace:not([hidden])",when:root=>!!root.querySelector('.wss-editor [data-wss-action="find"]'),steps:[{title:"Choose a few concepts",text:"Open Finder, search a topic and select the concepts you want. Its results start selected, so use None before ticking a small set.",target:".wss-editor [data-wss-action='find']",visual:"search"},{title:"Know where sets live",text:"Study sets stay in this browser. Library backup exports all saved sets; return after selecting concepts to name and order a set.",target:"[data-wss-action='backup'], .wss-library",visual:"privacy",optional:true}]},{id:"study-sets-selection",title:"Use your Finder selection",kind:"panel",priority:91,surface:"#study-sets-workspace:not([hidden])",when:root=>!!root.querySelector('.wss-editor [data-wss-action="create"]'),steps:[{title:"Create from this selection",text:"The concepts you selected in Finder are ready. Choose Create a set, then name and order them before saving.",target:".wss-editor [data-wss-action='create']",visual:"list"}]},{id:"study-sets",title:"Keep a study set",kind:"panel",priority:90,surface:"#study-sets-workspace:not([hidden])",when:root=>!!root.querySelector('.wss-fields'),steps:[{title:"Name and order the set",text:"Save selected Finder concepts under a name. Add a short preparation note, move items into the order you want, or remove an item before saving.",target:".wss-fields, .wss-items",visual:"list"},{title:"Keep a transfer copy",text:"Export Set backup for one set or draft, or Library backup for all sets. Set notes is readable Markdown, not an importable backup.",target:"[data-wss-action='draft-json'], [data-wss-action='backup'], .wss-actions",visual:"privacy"},{title:"Review when ready",text:"Choose Review this set to start a separate session. Saving the set alone changes neither mastery nor session progress; Review later is a separate bookmark.",target:"[data-wss-action='review'], .wss-editor",visual:"practice"}]},{id:"review-setup",title:"Start a review session",kind:"panel",priority:94,surface:"#study-session:not([hidden])",when:root=>!!root.querySelector(".ss-plan .ss-choices [data-ss-action='start']"),steps:[{title:"Choose a short queue",text:"Start a review from this saved set. The choices show the actual number available, up to five or ten, and follow your saved order.",target:".ss-plan .ss-choices [data-ss-action='start']",visual:"practice"}]},{id:"review-active",title:"Review one concept at a time",kind:"panel",priority:94,surface:"#study-session:not([hidden])",when:root=>!!root.querySelector(".ss-actions [data-ss-action='done']"),steps:[{title:"Try this concept",text:"Read the note or use Self-test or an available AI check before recording this step. A session step is separate from your mastery rating.",target:".ss-actions [data-ss-action='selftest']",visual:"practice"},{title:"Record and continue",text:"Choose Done & next after reviewing this concept, or Skip & next if you want to leave it for now. Done does not change mastery.",target:".ss-actions [data-ss-action='done']",visual:"progress"},{title:"Pause this session",text:"Choose Pause to save your queue position in this browser. Session options opens End session; it does not contain Pause.",target:".ss-actions [data-ss-action='pause']",visual:"privacy"}]},{id:"review-resume",title:"Resume a paused review",kind:"panel",priority:94,surface:"#study-session:not([hidden])",when:root=>!!root.querySelector(".ss-actions [data-ss-action='resume']"),steps:[{title:"Continue the saved queue",text:"Choose Resume review to return to the next concept. Your place is saved in this browser; an unfinished AI question is not restored.",target:".ss-actions [data-ss-action='resume']",visual:"practice"}]},{id:"review-finished",title:"Read your review summary",kind:"panel",priority:95,surface:"#study-session:not([hidden])",when:root=>!!root.querySelector(".ss-outcome"),steps:[{title:"Check what happened",text:"Review the Done, Skipped and Not reviewed items. Session progress records these actions separately from mastery ratings.",target:".ss-summary",visual:"progress"},{title:"Keep a copy",text:"Choose Download summary for a record of this finished session. You can start a fresh review from a saved set later.",target:".ss-actions [data-ss-action='summary']",visual:"list"}]},{id:"mastery-manager",title:"Inspect your learning record",kind:"panel",priority:90,surface:"#mm-panel",steps:[{title:"Filter the record",text:"Choose a course, type a concept or lecture, or filter by mastery level. Visited, unrated and explicitly Unknown are different states.",target:"#mm-filter, #mm-course, #mm-level-filters",visual:"search"},{title:"Inspect the evidence",text:"Open a concept card for its rating, visits and available AI check details. These are study records, not course grades.",target:"#mm-list",visual:"progress"},{title:"Change with care",text:"Use the level selector on a card to revise a rating. Data actions can remove records, so check the scope before confirming a deletion.",target:".mm-level, .mm-data-actions",visual:"privacy"}]},{id:"ai-check",title:"Try an AI concept check",kind:"panel",priority:92,surface:"#aiq-panel",steps:[{title:"Choose the check",text:"Read each question and select an answer before revealing feedback. An internet connection is required to check answers; an account is optional for practice.",target:".aiq-question, .aiq-options, #aiq-panel",visual:"practice"},{title:"Use the explanation",text:"Compare the returned explanation with your reasoning and the course source. If checking fails, your choice remains in the open quiz for Retry check answer.",target:".aiq-feedback, #aiq-panel",visual:"practice"},{title:"Choose your mastery",text:"Choose your own mastery rating after reading any suggested level. These repeatable questions are learning practice, not a confidential exam bank.",target:".aiq-result-card, #aiq-panel",visual:"progress"}]},{id:"concept-connections",title:"Trace concept connections",kind:"panel",priority:75,manualOnly:true,surface:"#lp-side-panel",when:root=>{const sheet=root.closest("#lp-mobile-sheet");return!sheet||sheet.classList.contains("lp-expanded");},steps:[{title:"Find earlier foundations",text:"Open or close Prerequisites to inspect recorded foundations. A page with no suggestions does not prove that no earlier knowledge is needed.",target:".lp-pres > summary",visual:"map"},{title:"Look ahead",text:"Open or close Dependents for concepts that use this one later. These links describe published pages, not the official teaching order.",target:".lp-deps > summary",visual:"map"},{title:"Explore related ideas",text:"Related concepts collects other published links. It is an exploration list; follow a title to read the separate note.",target:".lp-rel > summary",visual:"map"},{title:"Open a map",text:"Open concept maps for Nearby, Prerequisites and Dependents views. The map has its own controls and Guide.",target:"[data-lp-open-map]",visual:"map",optional:true},{title:"Follow a planned route",text:"Open Knowledge GPS when offered to see one route through recorded prerequisites. Check its start and target before using guided study.",target:"[data-lp-open-gps]",visual:"practice",optional:true}]},{id:"knowledge-gps",title:"Follow a guided study route",kind:"panel",priority:96,surface:"#lp-gps-modal.lp-open",steps:[{title:"Read the route",text:"Read Start, Target and the numbered cards to see what to review before the goal. Routes use published links and your study record.",target:".lp-gps-stats, .lp-gps-route",visual:"map"},{title:"Begin or continue",text:"Choose Start guided study for the first concept or Continue for the next available step. This browser keeps the route context.",target:"[data-lp-gps-start], [data-lp-gps-next-index]",visual:"practice"},{title:"Try another valid route",text:"Choose Another valid path to compare a different route through the published graph. Close returns to the concept page.",target:"[data-lp-gps-reroll], .lp-gps-close",visual:"map"}]},{id:"course-diagnostics",title:"Choose a course review target",kind:"panel",priority:94,surface:"#mk-course-mastery-map-modal .cmm-modal__dialog",steps:[{title:"Read the course summary",text:"Compare visited and rated counts before the readiness score. An unrated course is unassessed, not failed; visits can contribute some readiness. Open the information button for details.",target:".cmm-metrics, [data-cmm-course-readiness-info]",visual:"progress"},{title:"Scan the concept heatmap",text:"Select a concept square to inspect its evidence. Rows group lectures or weeks; with few ratings, low percentages mainly reflect missing records, not poor performance.",target:".cmm-stage .cmm-heatmap, [data-cmm-select-concept]",visual:"map"},{title:"Use the side summaries",text:"Open a side card for unit status, recent change or concept-state distribution. Its lecture link jumps to the expandable list below.",target:".cmm-stage__side, [data-cmm-jump-lecture]",visual:"progress"},{title:"Inspect one concept",text:examMode?"Open Current focus to compare mastery readiness, prerequisite readiness and local visits; follow its title to the note. These records are not course grades.":"Open Current focus to compare mastery readiness, prerequisite readiness, visits and AI checks. Public averages describe participating records, not a target grade.",target:".cmm-focuscard, .cmm-public-score-avgs",visual:"progress"},{title:"Filter the lecture list",text:"Toggle Low mastery readiness or Unvisited to narrow the expandable lists. Open a lecture or week to read its concept rows, then follow a concept link for definitions and examples.",target:"[data-cmm-filter], [data-cmm-lecture-toggle], .cmm-lecture__body",visual:"list"},{title:"Close and return",text:"Close the diagnostics dialog to return to the course hub. Your recorded visits and mastery ratings remain; this view does not assign course grades.",target:"[data-cmm-close]",visual:"progress"}]},{id:"map-nearby",title:"Explore the Nearby map",kind:"panel",priority:98,surface:"#lp-map-modal.lp-open",steps:[{title:"Start at this concept",text:"Use the tabs to switch from Nearby to Prerequisites or Dependents. Nearby starts with the current concept and its published neighbours.",target:".lp-map-tabs",visual:"map"},{title:"Preview, expand or open",text:"Select a side node to preview its actions, then choose Expand map or Open page. On a PC, hover also previews; selection alone does not expand.",target:".lp-mapstage a.lp-node:not(.is-cur)",visual:"map",action:"Choose a side node, then inspect its actions."},{title:"Pan and zoom",text:"Use minus, plus, the slider or Reset to zoom; drag the background to pan. On touch devices, pinch the map. Fullscreen gives the graph more room.",target:"[data-zoom-range], [data-zoom-reset], [data-lp-fullscreen]",visual:"map"},{title:"Choose masking",text:"Turn masking on to hide unfamiliar titles, then select a masked node to reveal it. This changes visibility without altering links or mastery.",target:".lp-map-option:has([data-lp-fog-switch])",visual:"privacy"},{title:"Discover optional chests",text:"Open a chest if one appears after expanding nodes. Signed-in accounts may receive server-decided treasure, subject to availability and daily limits.",target:".lp-map-chests, .lp-map-chest",visual:"shop",optional:true},{title:"Close to reset exploration",text:"Close dismisses the map and discards this session's added nodes and preview. Reopening starts from the original Nearby neighbourhood; your underlying study record remains separate.",target:".lp-close",visual:"map"}]},{id:"map-chest-reward",title:"Claim a map discovery",kind:"panel",priority:101,surface:".lp-map-chest-dialog[open]",steps:[{title:"Read the receipt",text:"Read the server-confirmed reward, then choose Keep exploring to return to the map. If the claim failed, Retry targets the same chest without a second award.",target:".lp-chest-reward-card, .lp-map-chest-dismiss",visual:"shop"}]},{id:"map-prerequisites",title:"Trace prerequisites",kind:"panel",priority:99,surface:"#lp-h1sg-modal.lp-open[data-lp-mode='toHere']",steps:[{title:"Read the direction",text:"Check the Prerequisites tab, then select a foundation node. If the filter is shown, use it to find a topic; paths follow published links.",target:"[data-lp-map-tab='toHere']",visual:"map"},{title:"Choose a learning path",text:"Select a route node to highlight a path from Start to Goal. The map reports how many concepts the path contains; this traces recorded links, not every mathematical prerequisite.",target:".lp-mapstage .lp-node, [data-lp-map-route-endpoints]",visual:"map"},{title:"Begin guided study",text:"After selecting a path, choose Start guided study when it appears. It follows the selected concepts in order; you can return to the map to choose another path.",target:"[data-lp-h1sg-dock-launch]",visual:"practice",optional:true},{title:"Adjust the view",text:"Drag the background to pan; use the slider, plus or minus to zoom and Reset to restore scale. Masking changes which unfamiliar titles are visible without changing links.",target:"[data-lp-h1sg-zoom-range], [data-lp-h1sg-zoom-reset], [data-lp-fog-switch]",visual:"map"},{title:"Switch or close",text:"Use the tabs for Nearby or Dependents. Close returns to the concept page; the map is an exploration aid rather than an official teaching order.",target:"[data-lp-map-tab='fromHere'], [data-lp-map-tab='local'], .lp-close",visual:"map"}]},{id:"map-dependents",title:"Trace later uses",kind:"panel",priority:99,surface:"#lp-h1sg-modal.lp-open[data-lp-mode='fromHere']",steps:[{title:"Read the direction",text:"Check the Dependents tab, then select a later topic. If the filter is shown, use it to find a page; paths follow published links.",target:"[data-lp-map-tab='fromHere']",visual:"map"},{title:"Choose a learning path",text:"Select a later concept to highlight a path from Start to Goal. An absent link means only that the published graph does not record it.",target:".lp-mapstage .lp-node, [data-lp-map-route-endpoints]",visual:"map"},{title:"Begin guided study",text:"After selecting a path, use Start guided study when it appears to follow its concepts in order. Return to the map to choose another target.",target:"[data-lp-h1sg-dock-launch]",visual:"practice",optional:true},{title:"Adjust visibility and scale",text:"Pan by dragging the background. Zoom with the slider or buttons and use Reset to recenter the view. Masking hides unfamiliar labels without deleting connections.",target:"[data-lp-h1sg-zoom-range], [data-lp-h1sg-zoom-reset], [data-lp-fog-switch]",visual:"map"},{title:"Return to foundations",text:"Switch to Prerequisites or Nearby when the later page assumes a missing step. Close when ready to return to the current concept.",target:"[data-lp-map-tab='toHere'], [data-lp-map-tab='local'], .lp-close",visual:"map"}]},{id:"random-entry",title:"Start random exploration",kind:"page",priority:22,surface:"#random-entry-message",path:"(?:^|/)random\\.html$",steps:[{title:"Follow the redirect",text:"Follow the redirect to a random published concept. If loading fails, choose Retry or use Finder to define a smaller pool.",target:"#random-entry-message, #random-entry-retry",visual:"search"}]},{id:"custom-random-redirect",title:"Find a focused revision pool",kind:"page",priority:22,surface:"#concept-finder-redirect",path:"(?:^|/)custom-random\\.html$",steps:[{title:"Continue in Finder",text:"Open Concept Finder to continue a former Custom Random route. A bookmarked query may carry over; select a pool before random revision.",target:"#concept-finder-redirect",visual:"search"}]},{id:"rankings",title:"Read rankings and honours",kind:"page",priority:24,surface:".wiki-rankings",path:"(?:^|/)trending\\.html$",steps:[{title:"Choose the board",text:"Choose a concept or learner board first. The value column names its measure; Explain can define the selected metric and each number.",target:"#trending-app .trending-block, #trending-app",visual:"progress"},{title:"Choose the period",text:"Use the tabs above that board for its available UTC periods. Monthly honours appear on XP and EOR Rating after a calendar month is settled.",target:".trending-tab[data-period]",visual:"list"},{title:"Interpret the limits",text:"Read rankings as optional activity comparisons, not a study plan. Opted-out people are absent; missing historical Collection Value is not zero.",target:".trending-block, details",visual:"privacy"}]},{id:"teaching-workbench",title:"Prepare a teaching review",kind:"page",priority:25,surface:"[data-teaching-workbench]",path:"(?:^|/)teaching\\.html$",steps:[{title:"Set the scope",text:"Choose a course and either one concept or a whole lecture or week. Then choose relationship depth and list order; begin with a small neighbourhood.",target:"[data-tw-form]",visual:"map"},{title:"Add your purpose",text:"Add an optional learning outcome and notes to shape the lesson review. Download or print to keep this page's text.",target:"[data-tw-notes-editor]",visual:"practice"},{title:"Build and verify",text:"Build the relationship review, follow concept links and check sources against your course materials. A missing graph link does not prove that no prerequisite exists.",target:"[data-tw-build], [data-tw-review]",visual:"list"},{title:"Take the result away",text:"Download Markdown or print the review if you need to keep it. Account backup does not include teaching notes from this page.",target:"[data-tw-download], [data-tw-print]",visual:"share"}]},{id:"arena",title:"Choose an Arena activity",kind:"panel",priority:95,surface:".ar-dialog[open]",steps:[{title:"Choose the activity",text:"Choose a live duel, a separate-time Ghost race, Weekend events or your record. Read the displayed course scope before playing.",target:".ar-nav",visual:"practice"},{title:"Read the current rules",text:"Open the rules in the selected section before an official run. Practice, skipped questions and unfinished matches can have different scoring and reward outcomes.",target:".ar-rules, .ar-content",visual:"list"},{title:"Check connection and status",text:"Check account connection and current status before official play. Loading, unanswered invitations or unavailable weekends do not mean a match has started.",target:".ar-status, .ar-connection",visual:"progress"}]},{id:"arena-duels",title:"Manage duel challenges",kind:"panel",priority:97,surface:".ar-dialog[open] .ar-hero:not(.ar-hero--events)",steps:[{title:"Check your invitations",text:"Open a Your challenges card to check its course, question count, timing and status. Live duels and Ghost races appear separately.",target:"[data-challenges], [data-ghosts]",visual:"list"},{title:"Invite from a profile",text:"Open another learner's public profile to challenge them. Live duels require both players online; Ghost races let each person complete the same questions at different times.",target:".ar-content .ar-empty, .ar-rules",visual:"profile"},{title:"Read the terms",text:"Open the duel or Ghost race rules for scoring, exits and rewards before agreeing to a stake or starting a timed run.",target:".ar-rules",visual:"practice"}]},{id:"arena-offer",title:"Set challenge terms",kind:"panel",priority:99,surface:".ar-dialog[open] .ar-form",when:root=>!!root.querySelector("[data-ar='send-offer']"),steps:[{title:"Choose the format and course",text:"Choose a live duel to play together or a Ghost race for separate runs. Pick a course and supported question count.",target:"[name='format'], [name='course'], [name='count'], [name='ghostCount']",visual:"practice"},{title:"Set timing and stake",text:"For a live duel, start when both are ready or choose a local scheduled time. Read any stake and account balance before sending; the server confirms the proposal.",target:"[name='when'], [name='start'], .ar-form [data-offer-note]",visual:"settings"},{title:"Send and watch status",text:"Send invitation, then return to Your challenges to see acceptance, counteroffers or expiry. Nothing is played merely by sending a Ghost race invitation.",target:"[data-ar='send-offer'], [data-ar='back']",visual:"share"}]},{id:"arena-challenge",title:"Review a duel invitation",kind:"panel",priority:98,surface:".ar-dialog[open] .ar-terms",steps:[{title:"Inspect the proposal",text:"Check opponent, course, question count, scheduled time, proposal revision and expiry. Any stake is shown separately before you decide.",target:".ar-terms, .ar-wager",visual:"list"},{title:"Choose a response",text:"Accept, suggest terms, decline or cancel according to your role and invitation state. Open the rules to see when a duel becomes rated and how leaving affects it.",target:".ar-actions, .ar-rules",visual:"practice"}]},{id:"arena-live-match",title:"Play a live duel",kind:"panel",priority:100,surface:".ar-dialog[open] .ar-scoreboard",steps:[{title:"Join the table",text:"Check both players and their scores. Choose I'm ready when the agreed time arrives; both players must be online and ready before the first question begins.",target:".ar-scoreboard, [data-ar='ready']",visual:"progress"},{title:"Answer each round",text:"Select an option when the question appears. A wrong choice brings a pause and is crossed out; the first correct answer earns that round's point.",target:".ar-round .ar-options, .ar-round .ar-note",visual:"practice"},{title:"Review and advance",text:"Read the explanation, then choose Next question. Both players must advance. Leaving a started match can affect its result, so read the confirmation before using Leave match.",target:".ar-explanation, [data-ar='next'], [data-ar='leave']",visual:"practice"}]},{id:"arena-ghost-race",title:"Play a Ghost race",kind:"panel",priority:99,surface:".ar-dialog[open] .ar-content",when:root=>/Ghost race/.test(root.querySelector(".ar-section-head .ar-eyebrow")?.textContent||""),steps:[{title:"Check the race status",text:"Check opponent, course, question count and deadline before starting. Each question's clock begins when it appears; allow time for a run.",target:".ar-section-head, .ar-ready",visual:"progress"},{title:"Answer and compare",text:"Choose an answer on each question, read the explanation, then continue. The second player races the first player's recorded times; wrong answers pause or end that question.",target:".ar-ghost-round, [data-ar='ghost-next']",visual:"practice"},{title:"Finish or step away",text:"Reopen a started run from Duels. Read the race card and confirmation before leaving or stalling, since either may affect the result.",target:"[data-ar='ghost-leave'], [data-ar='back'], .ar-ghost-rounds",visual:"privacy"}]},{id:"arena-record",title:"Read your competition record",kind:"panel",priority:98,surface:".ar-dialog[open] .ar-settings",steps:[{title:"Interpret the record",text:"Read rating, results, honours and recent activity separately. A provisional rating or unfinished event is not a final award.",target:".ar-record-stats, .ar-honors, .ar-history",visual:"progress"},{title:"Choose visibility",text:"Set invitations and public competition-record visibility separately, then choose Save preferences. These choices update your connected account.",target:".ar-settings [data-setting], [data-ar='save-settings']",visual:"privacy"}]},{id:"arena-weekend",title:"Play a weekend quiz",kind:"panel",priority:97,surface:".ar-dialog[open] .ar-hero--events",steps:[{title:"Check the weekend card",text:"Read included courses, lecture or week scope and availability on the calendar. No competition scheduled means an official run cannot start.",target:".ar-events",visual:"list"},{title:"Open one question at a time",text:"Open each of ten Quiz Sprint questions when ready. Its timer starts on opening; wrong answers pause and skipping earns zero.",target:".ar-content",visual:"practice"},{title:"Review after playing",text:"Review answered questions and final results after the weekend closes. Before settlement, the board is provisional; monthly honours follow displayed eligibility rules.",target:".ar-rules, .ar-content",visual:"progress"}]},{id:"arena-event-detail",title:"Review a weekend event",kind:"panel",priority:98,surface:".ar-dialog[open] .ar-puzzle-list",steps:[{title:"Check the event scope",text:"Read the dates, timezone and included course topics. A closed event permits practice but cannot add another official score; an unavailable card explains why no run starts.",target:".ar-section-head, .ar-rules[aria-label]",visual:"list"},{title:"Start or resume one run",text:"Choose Start my official run during an active event. Question cards show open, completed or practice status before you enter.",target:"[data-ar='start-event'], .ar-puzzle-list",visual:"practice"},{title:"Read results carefully",text:"Read event results as provisional until finalisation. Calendar export downloads an .ics file; website reminder controls cannot change an imported calendar.",target:".ar-leaders, [data-ar='calendar'], [data-ar='mute']",visual:"progress"}]},{id:"arena-sprint-question",title:"Answer a Sprint question",kind:"panel",priority:100,surface:".ar-dialog[open] .ar-content",when:root=>!!root.querySelector("[data-sprint-choice]"),steps:[{title:"Watch the question clock",text:"Read the prompt and choose one option while the clock runs. Official scoring rewards earlier correct answers; practice cannot change your score.",target:".ar-question, [data-puzzle-clock], [data-sprint-choice]",visual:"practice"},{title:"Use feedback before continuing",text:"Read feedback and the explanation before continuing. Wrong answers may pause choices; Skip ends an official question for zero points after confirmation.",target:".ar-puzzle-feedback, [data-ar='skip-puzzle'], .ar-puzzle-continue",visual:"practice"}]},{id:"exam-about",title:"Use the Exam Mode guide",kind:"page",priority:11,surface:"article.md-content__inner",path:"(?:^|/)about\\.html$",when:()=>examMode,steps:[{title:"Find published notes",text:"Start with the Course Material and Search sections. Finder combines names, course codes and lecture tags, while each course hub offers a narrower search.",target:"#course-material, #search-and-concept-finder",visual:"search"},{title:"Interpret local records",text:"Read Local Mastery for rating levels and Course diagnostics for their summary. Unrated differs from Unknown; records stay in this browser.",target:"#local-mastery, #course-diagnostics",visual:"progress"},{title:"Use only available revision",text:"Open Concept maps, Learning Path or random revision where available, and Self-test only where its control appears. Read Unavailable Features before planning online activity.",target:"#revision-modes, #unavailable-features",visual:"privacy"}]},{id:"about",title:"Use this site guide",kind:"page",priority:11,surface:".wiki-about",path:"(?:^|/)about\\.html$",when:()=>!examMode,steps:[{title:"Choose a task",text:"Choose a card to find a concept, revise a small set or prepare to teach. Optional activities have their own routes.",target:".wa-task-grid",visual:"list"},{title:"Keep the limits in view",text:"Check coverage and your lecturer's syllabus before relying on a Wiki route. Assessment guidance comes from the course, not this site.",target:".wh-hero-note, .wa-note",visual:"privacy"},{title:"Open precise rules when needed",text:"Open the detailed reference for rating definitions, backup boundaries, privacy, rewards or competition rules. Use its topic links for the exact section.",target:".wa-reference-links a[href*='about-reference']",visual:"list"}]},{id:"about-reference",title:"Use the detailed feature reference",kind:"page",priority:10,surface:".wiki-about",path:"(?:^|/)about-reference\\.html$",steps:[{title:"Jump to the exact rule",text:"Use section links to find rating, backup, privacy, competition or course-code details without reading the whole reference.",target:".wa-jump a[href^='#']",visual:"list"},{title:"Return to a shorter route",text:"The short site guide offers starting tasks. Explain is available beside controls when a particular label or number needs context.",target:".wiki-about > p:first-child",visual:"search"}]},{id:"contributors",title:"Meet the contributors",kind:"page",priority:12,surface:"article.md-content__inner",path:"(?:^|/)contributors\\.html$",steps:[{title:"Read the roles",text:"Read contributor and source credits here. For a broken link, unclear step or source issue, use the correction contact with its URL and description.",target:"h1, .wiki-contributors",visual:"share"}]}];window.MkGuidePages=(window.MkGuidePages||[]).concat(pages);})();